/**
 * Pre-projected Natural Earth 1:50m world country boundaries on the 1000×500 equirectangular canvas
 * (latitude span [-62°, +78°], longitude [-180°, +180°]), with Welsh-Powell neighbor-disjoint
 * color slots (0..7) so adjacent countries never share the same base thermal shade.
 */
export interface WorldCountryPolygon {
  code: string;
  /** Neighbor-disjoint palette index (0..7) guaranteeing adjacent countries are visually separated. */
  slot: number;
  /** Visual label center on the 1000×500 canvas. */
  cx: number;
  cy: number;
  /** Bounding box [minX, minY, maxX, maxY] on the 1000×500 canvas for smart country zoom. */
  bbox: [number, number, number, number];
  /** Projected SVG path data. */
  d: string;
}

